-- Seed 0005 — the Region VII (Central Visayas) academic catalog. **Generated file.**
--
-- Edit `scripts/build-region7-seed.mjs` and re-run `node scripts/build-region7-seed.mjs`.
-- Editing this file by hand works exactly once, until the next regeneration overwrites it, and
-- `npm run seed:region7:check` fails the build in the meantime.
--
-- ## What this file does
--
-- It is a **reset**, not an addition. Seed 0004 seeded a nationwide catalog — 20 institutions
-- from Diliman to Iligan — and this replaces it wholesale with the Region VII catalog described
-- in `Region VII Education Career Database.pdf` (2026-09-05, sourced from CHED RO VII
-- directories, institutional programme pages and PRC board registers).
--
-- The boundary is the point. RA 12000 re-established the Negros Island Region, so Region VII is
-- **Bohol and Cebu only** — Negros Oriental and Siquijor moved to NIR, and Silliman University,
-- which seed 0004 lists, is a Dumaguete institution that no longer belongs in this region's
-- catalog at all. A student in Cebu asking "where can I study this?" was being shown Manila.
--
-- ## What it deletes, and what that costs
--
-- Every college, programme, canonical programme, career and mapping in the database, in foreign
-- key order. That reaches further than the catalog: `recommendations` cascades from both
-- `careers` and `programs`, and `recommendation_explanations` cascades from that — so **every
-- student's stored recommendations are removed**, because every one of them points at a career
-- or programme that is about to stop existing.
--
-- That is recoverable and does not lose anything a student authored: assessment attempts,
-- results and chat conversations are untouched, and §27 recomputes a ranking from the stored
-- result on demand — `POST /student/recommendations/regenerate`, the button added by audit C4,
-- or its counselor-side equivalent. The first student to open the page after this seed runs
-- sees the empty state and a regenerate action, not an error.
--
-- Deletes are written explicitly and in dependency order rather than left to ON DELETE CASCADE:
-- the cascade is correct, but it depends on `PRAGMA foreign_keys` being on in whatever executes
-- this, and a seed that silently orphans half a schema because a pragma was off is not a risk
-- worth taking for four saved lines.
--
-- ## Idempotent
--
-- Delete-then-insert, with content-derived UUIDv5 primary keys. Running it twice produces the
-- same database as running it once, and the ids are stable across regenerations, so a
-- re-seed does not invalidate anything that recorded one.
--
-- Salary bands and `typical_riasec_code` are considered **estimates, not measurements** —
-- monthly PHP for the Central Visayas market, Holland codes from the standard occupational
-- interpretation of each role. Every one is editable in the admin catalog screens. Nothing here
-- is shown to a student as a citation.
--
-- Timestamps are ISO-8601 UTC (`strftime`), never SQLite's bare `CURRENT_TIMESTAMP`, which
-- renders as `2026-07-13 14:11:05` and which JavaScript reads as *local* time
-- (src/lib/datetime.ts).

-- --- Reset ------------------------------------------------------------------------------
--
-- Child before parent, all the way down. `recommendations` is emptied outright because its
-- CHECK constraint admits only CAREER and PROGRAM rows, and both targets are being deleted.

DELETE FROM recommendation_explanations;
DELETE FROM recommendations;
DELETE FROM program_careers;
DELETE FROM programs;
DELETE FROM program_catalog;
DELETE FROM careers;
DELETE FROM colleges;

-- --- Region VII address hierarchy -------------------------------------------------------
--
-- Region → Province → Town, migration 0011's tables. Seeded here rather than left NULL (which
-- is what seed 0004 did) because this catalog's defining property is a geographic boundary: a
-- college row that cannot say which province it is in cannot be checked against the boundary
-- it was selected for.
--
-- `code` is the PSGC 9-digit code. Nullable and advisory in the schema.
--
-- `INSERT OR IGNORE` here is doing something subtle: `regions`, `provinces` and `towns` carry
-- **partial unique indexes on name** (live rows only), so if an admin has already created
-- "Cebu City" through the address screens, these inserts are skipped and the ids below never
-- reach the table. The college inserts that follow therefore resolve their location by
-- *subquery on name*, not by the derived id — which finds whichever row actually exists and
-- cannot leave a college pointing at an id that was never inserted.

INSERT OR IGNORE INTO regions (id, code, name, created_at, updated_at) VALUES
('41a90bb1-76e4-559d-a541-d398781961cc', '070000000', 'Region VII (Central Visayas)', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));

INSERT OR IGNORE INTO provinces (id, region_id, code, name, created_at, updated_at) VALUES
('2b98ed98-88d0-532e-9ed2-bb6467f7b4b2', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), '072200000', 'Cebu', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('acc968d6-e98a-5032-98a1-1cb2a489c19f', (SELECT id FROM regions WHERE name = 'Region VII (Central Visayas)' COLLATE NOCASE AND deleted_at IS NULL), '071200000', 'Bohol', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));

